import 'package:equatable/equatable.dart';
class Medication extends Equatable { const Medication({required this.id,required this.name,required this.nameAr,required this.form,required this.strength,required this.manufacturer,required this.isControlled}); final String id,name,nameAr,form,strength,manufacturer; final bool isControlled; @override List<Object?> get props=>[id,name,nameAr,form,strength,manufacturer,isControlled]; }
class PatientMedication extends Equatable { const PatientMedication({required this.id,required this.patientId,required this.medicationId,required this.dose,required this.route,required this.frequency,required this.durationDays,required this.startDate,required this.prescribedBy,required this.isActive,required this.schedule}); final String id,patientId,medicationId,dose,route,frequency,prescribedBy; final int durationDays; final DateTime startDate; final bool isActive; final MedicationSchedule schedule; @override List<Object?> get props=>[id,patientId,medicationId,dose,route,frequency,durationDays,startDate,prescribedBy,isActive,schedule]; }
class MedicationSchedule extends Equatable { const MedicationSchedule({required this.timeOfDay,required this.daysOfWeek,required this.reminderEnabled,required this.reminderLeadMinutes}); final int timeOfDay; final Set<int> daysOfWeek; final bool reminderEnabled; final int reminderLeadMinutes; @override List<Object?> get props=>[timeOfDay,daysOfWeek,reminderEnabled,reminderLeadMinutes]; }
